    # Common date patterns
    patterns = [
        r'(\d{2}[/\-.]\d{2}[/\-.]\d{4})',  # DD/MM/YYYY or MM/DD/YYYY
        r'(\d{4}[/\-.]\d{2}[/\-.]\d{2})',  # YYYY/MM/DD
        r'(\d{2}[/\-.]\d{2}[/\-.]\d{2})',  # DD/MM/YY
    ]

    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            for fmt in ('%d/%m/%Y', '%d-%m-%Y', '%d.%m.%Y', '%Y/%m/%d', '%Y-%m-%d', '%Y.%m.%d', '%d/%m/%y', '%d-%m-%y'):
                try:
                    dt = datetime.strptime(match, fmt)
                    # Heuristic: receipts are usually recent. 
                    # If %y is used, strptime handles it. 
                    return dt.strftime('%Y-%m-%d')
                except ValueError:
                    continue
    return None

def extract_total(text):
    lines = text.split('\n')
    lines = [line.strip() for line in lines if line.strip()]

    priority_keywords = [
        r'GRAND TOTAL',
        r'TOTAL\s+RM',
        r'TOTAL:\s+RM',
        r'TOTAL\s+AMOUNT',
        r'TOTAL',
        r'AMOUNT',
        r'TOTAL\s+DUE',
        r'AMOUNT\s+DUE',
        r'BALANCE\s+DUE',
        r'NETT\s+TOTAL',
        r'NET\s+TOTAL'
    ]

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    amount_pattern = r'(\d{1,3}(?:,\d{3})*\.\d{2})'

    # Try keywords in priority order
    for kw in priority_keywords:
        for i, line in enumerate(lines):
            if re.search(kw, line, re.IGNORECASE):
                # Check if any exclusion keyword is in the line
                if any(excl in line.upper() for excl in exclusion_keywords):
                    continue

                # Try to find amount on the same line
                match = re.search(amount_pattern, line)
                if match:
                    return match.group(1).replace(',', '')

                # Try to find amount on the next line
                if i + 1 < len(lines):
                    match = re.search(amount_pattern, lines[i+1])
                    if match:
                        return match.group(1).replace(',', '')

    # Fallback: look for the last amount in the text that doesn't have exclusion keywords nearby
    all_amounts = []
    for i, line in enumerate(lines):
        if any(excl in line.upper() for excl in exclusion_keywords):
            continue
        matches = re.findall(amount_pattern, line)
        if matches:
            all_amounts.append(matches[-1].replace(',', ''))

    if all_amounts:
        return all_amounts[-1]

    return None

