def preprocess_image(img):
    # Convert to grayscale
    img = img.convert('L')
    # Resize to improve OCR on small text
    width, height = img.size
    img = img.resize((width * 2, height * 2), Image.Resampling.LANCZOS)
    # Apply a slight blur to reduce noise or use threshold
    # img = img.filter(ImageFilter.MedianFilter())
    return img

def parse_date(date_str):
    # Try to fix common OCR errors in date_str
    # Replace common misreads: 'S' -> '5', 'I' -> '1', 'O' -> '0', 'G' -> '6', 'B' -> '8'
    # But only if it makes sense in a date context

    # Try different separators
    date_str = re.sub(r'[.\-/]', '/', date_str)
    parts = date_str.split('/')
    if len(parts) != 3:
        return None

    d, m, y = parts
    # Clean up parts
    d = re.sub(r'\D', '', d)
    m = re.sub(r'\D', '', m)
    y = re.sub(r'\D', '', y)

    if not (d and m and y):
        return None

    # Handle common month errors like 62 -> 02
    if len(m) == 2 and m.startswith('6'):
        m = '0' + m[1]
    elif len(m) == 2 and m == '12':
        pass # Dec is ok
    elif len(m) == 2 and m[0] > '1':
        # if month is like 22, 32 etc, maybe first digit is wrong
        m = '0' + m[1]

    # Normalize year
    if len(y) == 2:
        y = '20' + y

    if len(d) > 2: d = d[:2]
    if len(m) > 2: m = m[:2]
    if len(y) > 4: y = y[:4]

    try:
        dt = datetime(int(y), int(m), int(d))
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        try:
            # Try MM/DD/YYYY
            dt = datetime(int(y), int(d), int(m))
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            return None

def extract_date(text):
    # Search for patterns like DD/MM/YYYY
    patterns = [
        r'(\d{1,2}[/\-.]\d{1,2}[/\-.]\d{2,4})',
        r'(\d{8})', # DDMMYYYY
    ]

    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            if pattern == r'(\d{8})':
                # Try DDMMYYYY
                d, m, y = match[:2], match[2:4], match[4:]
                res = parse_date(f"{d}/{m}/{y}")
                if res: return res
            else:
                res = parse_date(match)
                if res: return res
    return None

