        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED', 'ROUNDING', 'CASH'
    ]

    # Improved amount pattern: handle common OCR errors for digits or separators
    # But for now let's stick to standard and try to fix the text first

    def clean_amount(s):
